operation.add:
$cp_cb_lang_file = DIR_SYSTEM . 'library/cyberpunks_cb_lang.php';
if (is_file($cp_cb_lang_file)) {
	require_once($cp_cb_lang_file);
	call_user_func(array('CyberpunksCbLang', 'init'), $this->registry);
}
$cp_thousand_point = $this->config->get('module_cyberpunks_language_overrides_thousand_point');
$cp_thousand_map = array(
	'space' => ' ',
	'comma' => ',',
	'dot'   => '.',
	'nbsp'  => "\xc2\xa0",
	'none'  => ''
);
if (is_string($cp_thousand_point) && isset($cp_thousand_map[$cp_thousand_point])) {
	$language->set('thousand_point', $cp_thousand_map[$cp_thousand_point]);
}

if (is_file(DIR_SYSTEM . 'library/cyberpunks_cb_lang.php')) {
	require_once(DIR_SYSTEM . 'library/cyberpunks_cb_lang.php');
	call_user_func(array('CyberpunksCbLang', 'registerTwig'), $twig);
} else {
	// Library not on disk (half-finished OCMOD install): keep cb_lang defined so themes still render.
	$cp_cb_lang_passthrough = function ($source) {
		$args = func_get_args();
		array_shift($args);

		return $args ? vsprintf((string)$source, $args) : (string)$source;
	};

	if (class_exists('\\Twig\\TwigFunction')) {
		$twig->addFunction(new \Twig\TwigFunction('cb_lang', $cp_cb_lang_passthrough));
	} elseif (class_exists('Twig_SimpleFunction')) {
		$twig->addFunction(new \Twig_SimpleFunction('cb_lang', $cp_cb_lang_passthrough));
	}
}

$data['hreflangs'] = array();
$data['og_locale'] = '';
$data['og_locale_alternates'] = array();

$this->load->model('localisation/language');
$cyberpunks_languages = $this->model_localisation_language->getLanguages();
$cyberpunks_default_code = $this->config->get('config_language');

$url_data = $this->request->get;
unset($url_data['_route_']);
unset($url_data['language']);

if (!isset($url_data['route'])) {
	$cyberpunks_route = 'common/home';
} else {
	$cyberpunks_route = $url_data['route'];
	unset($url_data['route']);
}

$cyberpunks_query = '';
if ($url_data) {
	$cyberpunks_query = urldecode(http_build_query($url_data, '', '&'));
}

$cyberpunks_locale_map = function ($code) {
	$parts = explode('-', strtolower((string)$code));
	if (count($parts) >= 2) {
		return $parts[0] . '_' . strtoupper($parts[1]);
	}
	return str_replace('-', '_', (string)$code);
};

$cyberpunks_prev_language_id = $this->config->get('config_language_id');
$cyberpunks_prev_language_code = isset($this->session->data['language']) ? $this->session->data['language'] : $cyberpunks_default_code;

foreach ($cyberpunks_languages as $cyberpunks_language) {
	if (empty($cyberpunks_language['status'])) {
		continue;
	}

	$code = $cyberpunks_language['code'];
	$this->session->data['language'] = $code;
	$this->config->set('config_language_id', (int)$cyberpunks_language['language_id']);

	$href = $this->url->link($cyberpunks_route, $cyberpunks_query, true);

	$data['hreflangs'][] = array(
		'hreflang' => $code,
		'href'     => str_replace('&amp;', '&', $href)
	);

	$locale = $cyberpunks_locale_map($code);

	if ($code === $cyberpunks_prev_language_code) {
		$data['og_locale'] = $locale;
	} else {
		$data['og_locale_alternates'][] = $locale;
	}

	if ($code === $cyberpunks_default_code) {
		$data['hreflangs'][] = array(
			'hreflang' => 'x-default',
			'href'     => str_replace('&amp;', '&', $href)
		);
	}
}

$this->session->data['language'] = $cyberpunks_prev_language_code;
$this->config->set('config_language_id', $cyberpunks_prev_language_id);

if (!$data['og_locale'] && $cyberpunks_default_code) {
	$data['og_locale'] = $cyberpunks_locale_map($cyberpunks_default_code);
}

$cp_text_agree_tpl = (string)$this->language->get('text_agree');
$cp_text_agree_args = substr_count($cp_text_agree_tpl, '%s');
$cp_text_agree_url = $this->url->link('information/information', 'information_id=' . $this->config->get('config_checkout_id'), true);

if ($cp_text_agree_args <= 0) {
	$data['text_agree'] = $cp_text_agree_tpl;
} elseif ($cp_text_agree_args === 1) {
	$cp_text_agree_link = '<a href="' . $cp_text_agree_url . '" class="agree" target="_blank" rel="noopener noreferrer"><b>' . $information_info['title'] . '</b></a>';
	$data['text_agree'] = sprintf($cp_text_agree_tpl, $cp_text_agree_link);
} else {
	$data['text_agree'] = sprintf($cp_text_agree_tpl, $cp_text_agree_url, $information_info['title']);
}
